  1→package mdns
  2→
  3→import (
  4→	"bytes"
  5→	"context"
  6→	"errors"
  7→	"log/slog"
  8→	"math/rand/v2"
  9→	"net"
 10→	"sort"
 11→	"sync"
 12→	"time"
 13→)
 14→
 15→// RFC 6762 §8 的探测与宣告参数。
 16→const (
 17→	// probeCount 是探测次数（§8.1：发三次）。
 18→	probeCount = 3
 19→	// probeInterval 是探测间隔（§8.1：250 毫秒）。
 20→	probeInterval = 250 * time.Millisecond
 21→	// probeDefer 是首次探测前的随机等待上限（§8.1：0-250 毫秒，
 22→	// 避免整个网络同时上电时所有设备一起探测）。
 23→	probeDefer = 250 * time.Millisecond
 24→
 25→	// announceCount 是宣告次数（§8.3：至少两次，最多八次，间隔翻倍）。
 26→	announceCount = 3
 27→	// announceInterval 是首次宣告后的间隔（§8.3：一秒起步，之后翻倍）。
 28→	announceInterval = time.Second
 29→
 30→	// goodbyeCount 是退出时发送 TTL=0 记录的次数（§10.1）。
 31→	goodbyeCount = 2
 32→	// goodbyeInterval 是 goodbye 报文之间的间隔。
 33→	goodbyeInterval = 250 * time.Millisecond
 34→)
 35→
 36→// RFC 6762 §9 的冲突退避参数。
 37→const (
 38→	// conflictBackoff 是发生冲突后重新探测前的等待（§8.1：一秒）。
 39→	conflictBackoff = time.Second
 40→	// conflictRateLimit：10 秒内冲突超过 15 次就把间隔拉到 5 秒（§9）。
 41→	conflictRateWindow = 10 * time.Second
 42→	conflictRateCount  = 15
 43→	conflictSlowdown   = 5 * time.Second
 44→)
 45→
 46→// RFC 6762 §6 的应答延迟：共享记录要随机延迟 20-120 毫秒，
 47→// 让多台设备的回应错开，顺便给聚合留出机会。
 48→const (
 49→	sharedReplyDelayMin = 20 * time.Millisecond
 50→	sharedReplyDelayMax = 120 * time.Millisecond
 51→)
 52→
 53→// legacyTTL 是回应"传统单播查询"时的 TTL 上限（RFC 6762 §6.7）。
 54→//
 55→// 传统客户端（源端口不是 5353）不理解 cache-flush 语义，
 56→// 给它们的记录必须用很短的 TTL，最多 10 秒。
 57→const legacyTTL uint32 = 10
 58→
 59→var (
 60→	errStopped  = errors.New("mdns: responder 已停止")
 61→	errConflict = errors.New("mdns: 名字冲突")
 62→)
 63→
 64→// state 是 responder 的状态（RFC 6762 §8 的三个阶段）。
 65→type state int32
 66→
 67→const (
 68→	stateIdle state = iota
 69→	stateProbing
 70→	stateAnnouncing
 71→	stateResponding
 72→)
 73→
 74→// Responder 是一个 mDNS/DNS-SD responder。
 75→//
 76→// 生命周期：New -> Start(ctx) -> ... -> Stop()。
 77→// Start 不阻塞；Stop 会先发 goodbye 再关闭 socket。
 78→type Responder struct {
 79→	rs         *recordSet
 80→	ifaceNames []string
 81→	log        *slog.Logger
 82→
 83→	conn *conn
 84→
 85→	mu    sync.RWMutex
 86→	st    state
 87→	conns int // 已发生的冲突次数，决定改名后缀
 88→
 89→	conflictTimes []time.Time // 冲突时间戳，用于 §9 的限速判断
 90→
 91→	conflictCh chan struct{}
 92→
 93→	cancel   context.CancelFunc
 94→	loopDone chan struct{}
 95→	sendWG   sync.WaitGroup // 延迟应答的 goroutine
 96→	stopOnce sync.Once
 97→	started  bool
 98→}
 99→
100→// SetLogger 替换日志器。必须在 Start 之前调用。
101→func (r *Responder) SetLogger(l *slog.Logger) {
102→	if l != nil {
103→		r.log = l
104→	}
105→}
106→
107→// Start 打开组播 socket 并在后台开始探测 / 宣告 / 应答。
108→//
109→// ctx 取消等价于调用 Stop（但不会发 goodbye —— 想优雅退出请显式调用 Stop）。
110→func (r *Responder) Start(ctx context.Context) error {
111→	r.mu.Lock()
112→	if r.started {
113→		r.mu.Unlock()
114→		return errors.New("mdns: responder 已经启动过了")
115→	}
116→	r.started = true
117→	r.mu.Unlock()
118→
119→	c, err := openConn(r.ifaceNames, r.log)
120→	if err != nil {
121→		return err
122→	}
123→	r.conn = c
124→
125→	runCtx, cancel := context.WithCancel(context.WithoutCancel(ctx))
126→	r.cancel = cancel
127→	r.loopDone = make(chan struct{})
128→
129→	// 外部 ctx 取消时连带停止。
130→	if ctx.Done() != nil {
131→		go func() {
132→			select {
133→			case <-ctx.Done():
134→				cancel()
135→			case <-runCtx.Done():
136→			}
137→		}()
138→	}
139→
140→	go c.run(runCtx, r.handlePacket)
141→	go r.loop(runCtx)
142→
143→	r.log.Info("mDNS: 已启动",
144→		"instance", r.rs.instance, "host", r.rs.hostname(), "services", r.serviceTypes())
145→	return nil
146→}
147→
148→func (r *Responder) serviceTypes() []string {
149→	out := make([]string, len(r.rs.defs))
150→	for i, d := range r.rs.defs {
151→		out[i] = d.Type
152→	}
153→	return out
154→}
155→
156→// Stop 发送 goodbye（TTL=0）后关闭 responder。可重复调用。
157→func (r *Responder) Stop() {
158→	r.stopOnce.Do(func() {
159→		if r.conn == nil {
160→			return
161→		}
162→		// 只有已经宣告过的名字才需要撤回。
163→		if r.currentState() == stateResponding {
164→			r.sendGoodbye()
165→		}
166→		if r.cancel != nil {
167→			r.cancel()
168→		}
169→		if r.loopDone != nil {
170→			<-r.loopDone
171→		}
172→		r.sendWG.Wait()
173→		r.conn.Close()
174→		r.log.Info("mDNS: 已停止")
175→	})
176→}
177→
178→func (r *Responder) currentState() state {
179→	r.mu.RLock()
180→	defer r.mu.RUnlock()
181→	return r.st
182→}
183→
184→func (r *Responder) setState(s state) {
185→	r.mu.Lock()
186→	r.st = s
187→	r.mu.Unlock()
188→}
189→
190→// ---------------------------------------------------------------- 主循环
191→
192→func (r *Responder) loop(ctx context.Context) {
193→	defer close(r.loopDone)
194→
195→	for {
196→		if err := r.probe(ctx); err != nil {
197→			return // 只可能是 errStopped
198→		}
199→
200→		r.setState(stateAnnouncing)
201→		err := r.announce(ctx)
202→		switch {
203→		case errors.Is(err, errConflict):
204→			r.renameAfterConflict()
205→			if !sleepCtx(ctx, r.backoff()) {
206→				return
207→			}
208→			continue
209→		case err != nil:
210→			return
211→		}
212→
213→		r.setState(stateResponding)
214→		select {
215→		case <-ctx.Done():
216→			return
217→		case <-r.conflictCh:
218→			r.renameAfterConflict()
219→			if !sleepCtx(ctx, r.backoff()) {
220→				return
221→			}
222→		}
223→	}
224→}
225→
226→// probe 执行 RFC 6762 §8.1 的探测流程，冲突则改名重来。
227→func (r *Responder) probe(ctx context.Context) error {
228→	r.setState(stateProbing)
229→
230→	for {
231→		drain(r.conflictCh)
232→
233→		// §8.1：首次探测前随机等待 0-250ms。
234→		if !sleepCtx(ctx, rand.N(probeDefer)) {
235→			return errStopped
236→		}
237→
238→		conflicted := false
239→		for i := 0; i < probeCount && !conflicted; i++ {
240→			r.sendProbe()
241→			select {
242→			case <-ctx.Done():
243→				return errStopped
244→			case <-r.conflictCh:
245→				conflicted = true
246→			case <-time.After(probeInterval):
247→			}
248→		}
249→		if !conflicted {
250→			return nil
251→		}
252→
253→		r.renameAfterConflict()
254→		if !sleepCtx(ctx, r.backoff()) {
255→			return errStopped
256→		}
257→	}
258→}
259→
260→// announce 执行 RFC 6762 §8.3 的宣告流程。
261→func (r *Responder) announce(ctx context.Context) error {
262→	interval := announceInterval
263→	for i := 0; i < announceCount; i++ {
264→		r.sendAnnouncement()
265→		if i == announceCount-1 {
266→			break
267→		}
268→		select {
269→		case <-ctx.Done():
270→			return errStopped
271→		case <-r.conflictCh:
272→			return errConflict
273→		case <-time.After(interval):
274→		}
275→		interval *= 2 // §8.3：间隔逐次翻倍
276→	}
277→	return nil
278→}
279→
280→// renameAfterConflict 按 RFC 6762 §9 改名。
281→func (r *Responder) renameAfterConflict() {
282→	r.mu.Lock()
283→	r.conns++
284→	n := r.conns
285→	r.conflictTimes = append(r.conflictTimes, time.Now())
286→	r.mu.Unlock()
287→
288→	old := r.rs.instance
289→	r.rs.rename(n)
290→	r.log.Warn("mDNS: 检测到名字冲突，已改名",
291→		"old", old, "new", r.rs.instance, "host", r.rs.hostname(), "conflicts", n)
292→}
293→
294→// backoff 返回冲突后重新探测前的等待时间。
295→//
296→// RFC 6762 §9：10 秒内冲突超过 15 次说明网络里有别的东西在跟我们抢，
297→// 把重试间隔拉长到 5 秒，避免把链路吵爆。
298→func (r *Responder) backoff() time.Duration {
299→	r.mu.Lock()
300→	defer r.mu.Unlock()
301→
302→	cutoff := time.Now().Add(-conflictRateWindow)
303→	kept := r.conflictTimes[:0]
304→	for _, t := range r.conflictTimes {
305→		if t.After(cutoff) {
306→			kept = append(kept, t)
307→		}
308→	}
309→	r.conflictTimes = kept
310→
311→	if len(kept) > conflictRateCount {
312→		return conflictSlowdown
313→	}
314→	return conflictBackoff
315→}
316→
317→// ---------------------------------------------------------------- 发送
318→
319→// sendProbe 发送探测查询（RFC 6762 §8.1）。
320→//
321→// 格式：Question 用 qtype=ANY、QU=1；Authority 段放我们打算宣告的记录，
322→// 供对端做 §8.2 的同时探测仲裁。
323→func (r *Responder) sendProbe() {
324→	names := r.rs.uniqueNames()
325→	for i := range r.conn.ifaces {
326→		ifi := &r.conn.ifaces[i]
327→		m := &Message{}
328→		for _, n := range names {
329→			m.Questions = append(m.Questions, Question{
330→				Name: n, Type: TypeANY, Class: ClassIN, Unicast: true,
331→			})
332→		}
333→		// 提议中的记录不置 cache-flush：此刻我们还没有拥有这些名字。
334→		for _, rec := range r.proposedRecords(ifi) {
335→			rec.CacheFlush = false
336→			m.Authorities = append(m.Authorities, rec)
337→		}
338→		r.conn.sendMulticast(m, ifi.Index)
339→	}
340→}
341→
342→// sendAnnouncement 发送无请求应答（RFC 6762 §8.3）。
343→func (r *Responder) sendAnnouncement() {
344→	for i := range r.conn.ifaces {
345→		ifi := &r.conn.ifaces[i]
346→		m := &Message{
347→			Flags:   FlagResponse | FlagAuthoritative,
348→			Answers: r.recordsFor(ifi),
349→		}
350→		r.conn.sendMulticast(m, ifi.Index)
351→	}
352→}
353→
354→// sendGoodbye 发送 TTL=0 的记录，让邻居立刻清掉缓存（RFC 6762 §10.1）。
355→func (r *Responder) sendGoodbye() {
356→	for n := 0; n < goodbyeCount; n++ {
357→		for i := range r.conn.ifaces {
358→			ifi := &r.conn.ifaces[i]
359→			// NSEC 是否定记录，撤回它没有意义，只撤回正面记录。
360→			recs := withTTL(withoutType(r.recordsFor(ifi), TypeNSEC), ttlGoodbye)
361→			m := &Message{
362→				Flags:   FlagResponse | FlagAuthoritative,
363→				Answers: recs,
364→			}
365→			r.conn.sendMulticast(m, ifi.Index)
366→		}
367→		if n != goodbyeCount-1 {
368→			time.Sleep(goodbyeInterval)
369→		}
370→	}
371→	r.log.Debug("mDNS: 已发送 goodbye（TTL=0）")
372→}
373→
374→// ---------------------------------------------------------------- 记录集合
375→
376→// proposedRecords 是探测时放进 Authority 段的记录：只要正面记录，不含 NSEC。
377→func (r *Responder) proposedRecords(ifi *net.Interface) []Record {
378→	out := r.rs.serviceRecords()
379→	out = append(out, r.rs.addressRecords(ifi)...)
380→	return withoutType(out, TypePTR) // PTR 是共享记录，不参与唯一性探测
381→}
382→
383→// recordsFor 返回在某张网卡上要宣告 / 应答的全部记录。
384→//
385→// ifi 为 nil 表示平台没告诉我们收包网卡，只能把所有网卡的地址都带上。
386→func (r *Responder) recordsFor(ifi *net.Interface) []Record {
387→	out := r.rs.serviceRecords()
388→
389→	var hasV4, hasV6 bool
390→	for _, x := range r.chooseIfaces(ifi) {
391→		addrs := r.rs.addressRecords(x)
392→		for _, a := range addrs {
393→			if a.Type() == TypeA {
394→				hasV4 = true
395→			} else {
396→				hasV6 = true
397→			}
398→		}
399→		out = append(out, addrs...)
400→	}
401→	if nsec, ok := r.rs.hostNSEC(hasV4, hasV6); ok {
402→		out = append(out, nsec)
403→	}
404→	out = append(out, r.rs.instanceNSECs()...)
405→	return out
406→}
407→
408→// ownRecords 返回用于冲突判定的正面记录（全部网卡）。
409→func (r *Responder) ownRecords() []Record {
410→	out := r.rs.serviceRecords()
411→	for i := range r.conn.ifaces {
412→		out = append(out, r.rs.addressRecords(&r.conn.ifaces[i])...)
413→	}
414→	return out
415→}
416→
417→func (r *Responder) chooseIfaces(ifi *net.Interface) []*net.Interface {
418→	if ifi != nil {
419→		return []*net.Interface{ifi}
420→	}
421→	out := make([]*net.Interface, 0, len(r.conn.ifaces))
422→	for i := range r.conn.ifaces {
423→		out = append(out, &r.conn.ifaces[i])
424→	}
425→	return out
426→}
427→
428→func (r *Responder) ifaceByIndex(idx int) *net.Interface {
429→	if idx == 0 {
430→		return nil
431→	}
432→	for i := range r.conn.ifaces {
433→		if r.conn.ifaces[i].Index == idx {
434→			return &r.conn.ifaces[i]
435→		}
436→	}
437→	return nil
438→}
439→
440→// ---------------------------------------------------------------- 收包处理
441→
442→func (r *Responder) handlePacket(p packet) {
443→	m := p.msg
444→	// RFC 6762 §18.3：OPCODE 不是 0（标准查询）的报文一律忽略。
445→	if m.Flags.Opcode() != 0 {
446→		return
447→	}
448→	// §18.11：RCODE 不为 0 的报文也要忽略。
449→	if m.Flags.RCode() != 0 {
450→		return
451→	}
452→
453→	if m.Flags.IsResponse() {
454→		r.checkConflicts(m.Answers)
455→		r.checkConflicts(m.Additionals)
456→		return
457→	}
458→
459→	// 查询报文里也可能夹带别人的 Authority（同时探测），先做仲裁。
460→	if r.currentState() == stateProbing {
461→		r.checkProbeTiebreak(m)
462→		return
463→	}
464→	if r.currentState() != stateResponding {
465→		return // 宣告阶段还没稳定，先不应答
466→	}
467→	r.answerQuery(p)
468→}
469→
470→// checkConflicts 检查对方的应答是否与我们宣告的记录冲突（RFC 6762 §9）。
471→func (r *Responder) checkConflicts(records []Record) {
472→	if r.currentState() == stateIdle {
473→		return
474→	}
475→	for _, rec := range records {
476→		if r.isConflict(rec) {
477→			r.signalConflict(rec)
478→			return
479→		}
480→	}
481→}
482→
483→// isConflict 判断收到的一条记录是否与我们的记录冲突。
484→//
485→// 判定规则：名字与类型都是我们的，但 rdata 不在我们的集合里。
486→// 反过来说，rdata 完全一致的记录不算冲突 —— 那多半是我们自己发出去、
487→// 又通过组播回环收回来的报文。
488→func (r *Responder) isConflict(rec Record) bool {
489→	switch rec.Type() {
490→	case TypePTR:
491→		// PTR 是共享记录，多台主机同时宣告同一个服务类型完全正常。
492→		return false
493→	case TypeNSEC:
494→		// NSEC 的类型位图与网卡相关（只有 IPv4 的网卡不会有 AAAA），
495→		// 拿它判冲突会误报，直接跳过。
496→		return false
497→	}
498→	if !r.rs.ownsName(rec.Name) {
499→		return false
500→	}
501→
502→	sameKey := false
503→	for _, own := range r.ownRecords() {
504→		if !own.SameKey(rec) {
505→			continue
506→		}
507→		sameKey = true
508→		if rdataEqual(own.Data, rec.Data) {
509→			return false
510→		}
511→	}
512→	return sameKey
513→}
514→
515→func (r *Responder) signalConflict(rec Record) {
516→	r.log.Debug("mDNS: 收到冲突记录", "record", rec.String())
517→	select {
518→	case r.conflictCh <- struct{}{}:
519→	default: // 已经有一个未处理的冲突信号，不必重复
520→	}
521→}
522→
523→// checkProbeTiebreak 处理"同时探测"（RFC 6762 §8.2）。
524→//
525→// 两台机器同时探测同一个名字时，比较双方 Authority 段里的记录，
526→// 字典序大的一方获胜；输的一方改名。
527→func (r *Responder) checkProbeTiebreak(m *Message) {
528→	if len(m.Authorities) == 0 {
529→		return
530→	}
531→	names := r.rs.uniqueNames()
532→	for _, name := range names {
533→		theirs := recordsNamed(m.Authorities, name)
534→		if len(theirs) == 0 {
535→			continue
536→		}
537→		ours := recordsNamed(r.ownRecords(), name)
538→		if len(ours) == 0 {
539→			continue
540→		}
541→		if tiebreakLost(ours, theirs) {
542→			r.log.Debug("mDNS: 同时探测仲裁失败", "name", name)
543→			r.signalConflict(theirs[0])
544→			return
545→		}
546→	}
547→}
548→
549→// tiebreakLost 按 RFC 6762 §8.2.1 比较两组记录，返回 true 表示我们输了。
550→//
551→// 规则：两边各自按 (class, type, rdata) 字典序排序后逐条比较，
552→// 第一处不同就决出胜负；记录少的一方输。
553→func tiebreakLost(ours, theirs []Record) bool {
554→	a := sortedRDataKeys(ours)
555→	b := sortedRDataKeys(theirs)
556→	for i := 0; i < len(a) && i < len(b); i++ {
557→		if c := bytes.Compare(a[i], b[i]); c != 0 {
558→			return c < 0
559→		}
560→	}
561→	return len(a) < len(b)
562→}
563→
564→// sortedRDataKeys 把记录编码成可比较的字节串并排序。
565→//
566→// 每条记录编码为 class(2) + type(2) + rdata，全部大端，与 §8.2.1 的
567→// "按 class、type、rdata 依次比较"等价。
568→func sortedRDataKeys(records []Record) [][]byte {
569→	out := make([][]byte, 0, len(records))
570→	for _, rec := range records {
571→		if rec.Data == nil {
572→			continue
573→		}
574→		key := []byte{
575→			byte(uint16(rec.Class) >> 8), byte(uint16(rec.Class)),
576→			byte(uint16(rec.Data.Type()) >> 8), byte(uint16(rec.Data.Type())),
577→		}
578→		body, err := rec.Data.pack(nil)
579→		if err != nil {
580→			continue
581→		}
582→		out = append(out, append(key, body...))
583→	}
584→	sort.Slice(out, func(i, j int) bool { return bytes.Compare(out[i], out[j]) < 0 })
585→	return out
586→}
587→
588→// ---------------------------------------------------------------- 应答查询
589→
590→func (r *Responder) answerQuery(p packet) {
591→	ifi := r.ifaceByIndex(p.ifIndex)
592→	pool := r.recordsFor(ifi)
593→
594→	var (
595→		answers []Record
596→		shared  bool
597→	)
598→	for _, q := range p.msg.Questions {
599→		for _, rec := range pool {
600→			if !rec.Matches(q) || containsRecord(answers, rec) {
601→				continue
602→			}
603→			answers = append(answers, rec)
604→			// 没有 cache-flush 位的就是共享记录（PTR），回应要随机延迟。
605→			if !rec.CacheFlush {
606→				shared = true
607→			}
608→		}
609→	}
610→	if len(answers) == 0 {
611→		return
612→	}
613→
614→	// RFC 6762 §7.1 已知答案抑制：对方缓存里还很新鲜的记录就别再发了。
615→	answers = suppressKnownAnswers(answers, p.msg.Answers)
616→	if len(answers) == 0 {
617→		return
618→	}
619→
620→	additionals := r.additionalsFor(answers, pool)
621→
622→	// RFC 6762 §5.5：源端口不是 5353 的是"传统单播查询"，必须单播回应，
623→	// 并且要带上原问题、复用原 ID、TTL 压到 10 秒以内（§6.7）。
624→	legacy := p.src.Port != mdnsPort
625→	// §5.4：QU 位要求单播回应。
626→	unicast := legacy || anyUnicastQuestion(p.msg.Questions)
627→
628→	resp := &Message{Flags: FlagResponse | FlagAuthoritative}
629→	if legacy {
630→		resp.ID = p.msg.ID
631→		resp.Questions = p.msg.Questions
632→		answers = capTTL(answers, legacyTTL)
633→		additionals = capTTL(additionals, legacyTTL)
634→		// 传统客户端不认识 cache-flush 位，必须清掉（§6.7）。
635→		answers = withoutCacheFlush(answers)
636→		additionals = withoutCacheFlush(additionals)
637→	}
638→	resp.Answers = answers
639→	resp.Additionals = additionals
640→
641→	delay := time.Duration(0)
642→	if !unicast && (shared || len(p.msg.Questions) > 1) {
643→		// §6：共享记录或多问题查询，随机延迟 20-120ms 错峰。
644→		delay = sharedReplyDelayMin + rand.N(sharedReplyDelayMax-sharedReplyDelayMin)
645→	}
646→
647→	send := func() {
648→		if unicast {
649→			r.conn.sendUnicast(resp, p.src, p.v6)
650→			return
651→		}
652→		r.conn.sendMulticast(resp, p.ifIndex)
653→	}
654→
655→	if delay == 0 {
656→		send()
657→		return
658→	}
659→	r.sendWG.Add(1)
660→	go func() {
661→		defer r.sendWG.Done()
662→		time.Sleep(delay)
663→		send()
664→	}()
665→}
666→
667→// additionalsFor 按 RFC 6762 §6 附带"对方接下来一定会问"的记录：
668→// 回 PTR 就顺带 SRV/TXT/地址，回 SRV 就顺带地址。
669→func (r *Responder) additionalsFor(answers, pool []Record) []Record {
670→	var out []Record
671→	add := func(rec Record) {
672→		if containsRecord(answers, rec) || containsRecord(out, rec) {
673→			return
674→		}
675→		out = append(out, rec)
676→	}
677→
678→	host := r.rs.hostname()
679→	wantHostAddrs := false
680→
681→	for _, a := range answers {
682→		switch d := a.Data.(type) {
683→		case PTR:
684→			// 服务实例的 SRV / TXT / NSEC
685→			for _, rec := range pool {
686→				if EqualName(rec.Name, d.Target) &&
687→					(rec.Type() == TypeSRV || rec.Type() == TypeTXT || rec.Type() == TypeNSEC) {
688→					add(rec)
689→				}
690→			}
691→			wantHostAddrs = true
692→		case SRV:
693→			if EqualName(d.Target, host) {
694→				wantHostAddrs = true
695→			}
696→		}
697→	}
698→
699→	if wantHostAddrs {
700→		for _, rec := range pool {
701→			if !EqualName(rec.Name, host) {
702→				continue
703→			}
704→			switch rec.Type() {
705→			case TypeA, TypeAAAA, TypeNSEC:
706→				add(rec)
707→			}
708→		}
709→	}
710→	return out
711→}
712→
713→// suppressKnownAnswers 实现 RFC 6762 §7.1 的已知答案抑制。
714→//
715→// 只有当对方缓存里的剩余 TTL 大于我们记录 TTL 的一半时才抑制；
716→// 否则对方的缓存快过期了，还是该重发。
717→func suppressKnownAnswers(answers, known []Record) []Record {
718→	if len(known) == 0 {
719→		return answers
720→	}
721→	out := make([]Record, 0, len(answers))
722→	for _, a := range answers {
723→		suppressed := false
724→		for _, k := range known {
725→			if a.Equal(k) && k.TTL > a.TTL/2 {
726→				suppressed = true
727→				break
728→			}
729→		}
730→		if !suppressed {
731→			out = append(out, a)
732→		}
733→	}
734→	return out
735→}
736→
737→// ---------------------------------------------------------------- 小工具
738→
739→func anyUnicastQuestion(qs []Question) bool {
740→	for _, q := range qs {
741→		if q.Unicast {
742→			return true
743→		}
744→	}
745→	return false
746→}
747→
748→func containsRecord(list []Record, rec Record) bool {
749→	for _, x := range list {
750→		if x.Equal(rec) {
751→			return true
752→		}
753→	}
754→	return false
755→}
756→
757→func recordsNamed(list []Record, name string) []Record {
758→	var out []Record
759→	for _, rec := range list {
760→		if EqualName(rec.Name, name) {
761→			out = append(out, rec)
762→		}
763→	}
764→	return out
765→}
766→
767→func withoutType(list []Record, t Type) []Record {
768→	out := make([]Record, 0, len(list))
769→	for _, rec := range list {
770→		if rec.Type() != t {
771→			out = append(out, rec)
772→		}
773→	}
774→	return out
775→}
776→
777→func withoutCacheFlush(list []Record) []Record {
778→	out := make([]Record, len(list))
779→	copy(out, list)
780→	for i := range out {
781→		out[i].CacheFlush = false
782→	}
783→	return out
784→}
785→
786→func capTTL(list []Record, max uint32) []Record {
787→	out := make([]Record, len(list))
788→	copy(out, list)
789→	for i := range out {
790→		if out[i].TTL > max {
791→			out[i].TTL = max
792→		}
793→	}
794→	return out
795→}
796→
797→func drain(ch chan struct{}) {
798→	for {
799→		select {
800→		case <-ch:
801→		default:
802→			return
803→		}
804→	}
805→}
806→
807→// sleepCtx 睡眠 d，被取消时返回 false。
808→func sleepCtx(ctx context.Context, d time.Duration) bool {
809→	if d <= 0 {
810→		return ctx.Err() == nil
811→	}
812→	t := time.NewTimer(d)
813→	defer t.Stop()
814→	select {
815→	case <-ctx.Done():
816→		return false
817→	case <-t.C:
818→		return true
819→	}
820→}
