 31→// ValidationErrors 汇总一次校验中发现的**全部**问题。
 32→//
 33→// 一次性报出所有错误，避免用户改一个跑一次。
 34→type ValidationErrors []FieldError
 35→
 36→func (e ValidationErrors) Error() string {
 37→	if len(e) == 1 {
 38→		return "配置校验失败: " + e[0].Error()
 39→	}
 40→	var b strings.Builder
 41→	fmt.Fprintf(&b, "配置校验失败，共 %d 处问题:", len(e))
 42→	for _, fe := range e {
 43→		b.WriteString("\n  - " + fe.Error())
 44→	}
 45→	return b.String()
 46→}
