 48→// add 追加一条错误。
 49→func (e *ValidationErrors) add(field, format string, args ...any) {
 50→	*e = append(*e, FieldError{Field: field, Msg: fmt.Sprintf(format, args...)})
 51→}
 52→
 53→// 合法方言字符串，从低到高排列。索引即优先级。
 54→//
 55→// MS-SMB2 §2.2.3：0x0202 / 0x0210 / 0x0300 / 0x0302 / 0x0311。
 56→// 这里只做字符串校验，不引入 internal/smb（config 不依赖协议层）。
 57→var dialectOrder = []string{"2.0.2", "2.1", "3.0", "3.0.2", "3.1.1"}
 58→
 59→// DialectNames 返回全部合法的方言字符串（从低到高）。
 60→func DialectNames() []string {
 61→	out := make([]string, len(dialectOrder))
 62→	copy(out, dialectOrder)
 63→	return out
 64→}
 65→
 66→// dialectRank 返回方言的序号，非法返回 -1。
 67→func dialectRank(s string) int {
 68→	for i, d := range dialectOrder {
 69→		if d == s {
 70→			return i
 71→		}
 72→	}
 73→	return -1
 74→}
 75→
 76→// 共享名非法字符。
 77→//
 78→// MS-SRVS §2.2.4.22 / Windows 约定：共享名不得包含以下字符，
 79→// 也不得包含控制字符。长度上限 80 个字符。
 80→const shareNameInvalidChars = `\/:*?"<>|+;,=[]` + "\x00"
 81→
 82→// ShareNameMaxLen 是共享名最大长度（MS-SRVS 约定 80）。
 83→const ShareNameMaxLen = 80
 84→
 85→// Validate 校验配置。调用前应先执行 ApplyDefaults。
 86→//
 87→// 返回的 error 若非 nil，其动态类型一定是 ValidationErrors。
 88→func Validate(c *Config) error {
 89→	var errs ValidationErrors
 90→
 91→	validateServer(c, &errs)
 92→	validateListen(c, &errs)
 93→	validateShares(c, &errs)
 94→	validateAuth(c, &errs)
 95→	validateMDNS(c, &errs)
 96→	validateLog(c, &errs)
 97→
 98→	if len(errs) == 0 {
 99→		return nil
100→	}
101→	return errs
102→}
103→
104→func validateServer(c *Config, errs *ValidationErrors) {
105→	if c.Server.Name == "" {
106→		errs.add("server.name", "不能为空（留空时会自动使用系统主机名，取不到主机名请显式指定）")
107→	} else if len(c.Server.Name) > 15 {
108→		errs.add("server.name", "长度 %d 超过 NetBIOS 上限 15 字节: %q", len(c.Server.Name), c.Server.Name)
109→	}
110→	if strings.ContainsAny(c.Server.Name, shareNameInvalidChars+" .") {
111→		errs.add("server.name", "含非法字符（不能有空格、点或 %s）: %q", shareNameInvalidChars, c.Server.Name)
112→	}
113→
114→	if c.Server.Domain == "" {
115→		errs.add("server.domain", "不能为空，默认应为 %q", DefaultDomain)
116→	} else if len(c.Server.Domain) > 15 {
117→		errs.add("server.domain", "长度 %d 超过 NetBIOS 上限 15 字节: %q", len(c.Server.Domain), c.Server.Domain)
118→	}
119→
120→	minRank := dialectRank(c.Server.MinDialect)
121→	maxRank := dialectRank(c.Server.MaxDialect)
122→	if minRank < 0 {
123→		errs.add("server.min_dialect", "非法方言 %q，可选值: %s", c.Server.MinDialect, strings.Join(dialectOrder, ", "))
124→	}
125→	if maxRank < 0 {
126→		errs.add("server.max_dialect", "非法方言 %q，可选值: %s", c.Server.MaxDialect, strings.Join(dialectOrder, ", "))
127→	}
128→	if minRank >= 0 && maxRank >= 0 && minRank > maxRank {
129→		errs.add("server.min_dialect", "min_dialect (%s) 不能高于 max_dialect (%s)", c.Server.MinDialect, c.Server.MaxDialect)
130→	}
131→
132→	// SMB3 加密最低要求 3.0（MS-SMB2 §3.3.5.4）。
133→	if c.Server.EncryptionRequired && maxRank >= 0 && maxRank < dialectRank("3.0") {
134→		errs.add("server.encryption_required", "要求加密但 max_dialect 为 %s，SMB3 加密最低需要 3.0", c.Server.MaxDialect)
135→	}
136→
137→	if c.Server.MaxConnections < 0 {
138→		errs.add("server.max_connections", "不能为负数（0 表示不限），当前 %d", c.Server.MaxConnections)
139→	}
140→}
141→
142→func validateListen(c *Config, errs *ValidationErrors) {
143→	for i, a := range c.Listen.Addresses {
144→		field := fmt.Sprintf("listen.addresses[%d]", i)
145→		if a == "" {
146→			errs.add(field, "不能为空字符串（若要监听全部地址请把 addresses 整个留空）")
147→			continue
148→		}
149→		if net.ParseIP(a) == nil {
150→			errs.add(field, "不是合法 IP 地址: %q（这里只接受 IP，不接受主机名，端口写在 listen.port）", a)
151→		}
152→	}
153→
154→	if c.Listen.Port < 1 || c.Listen.Port > 65535 {
155→		errs.add("listen.port", "端口必须在 1-65535 之间，当前 %d", c.Listen.Port)
156→	}
157→}
158→
159→func validateShares(c *Config, errs *ValidationErrors) {
160→	if len(c.Shares) == 0 {
161→		errs.add("shares", "至少要配置一个共享目录，否则服务没有任何可用内容")
162→		return
163→	}
164→
165→	seen := make(map[string]int, len(c.Shares))
166→	for i := range c.Shares {
167→		s := &c.Shares[i]
168→		prefix := fmt.Sprintf("shares[%d]", i)
169→		validateShareName(s, i, prefix, seen, errs)
170→		validateSharePath(s, prefix, errs)
171→		validateShareMetadataPath(s, prefix, errs)
172→
173→		if s.TimeMachine && s.ReadOnly {
174→			errs.add(prefix+".time_machine", "共享 %q 标记为 Time Machine 目标但同时是只读，备份会失败", s.Name)
175→		}
176→	}
177→}
178→
179→func validateShareName(s *Share, idx int, prefix string, seen map[string]int, errs *ValidationErrors) {
180→	if s.Name == "" {
181→		errs.add(prefix+".name", "共享名不能为空")
182→		return
183→	}
184→	if len(s.Name) > ShareNameMaxLen {
185→		errs.add(prefix+".name", "共享名长度 %d 超过上限 %d: %q", len(s.Name), ShareNameMaxLen, s.Name)
186→	}
187→	if strings.ContainsAny(s.Name, shareNameInvalidChars) {
188→		errs.add(prefix+".name", "共享名 %q 含非法字符（不允许 %s）", s.Name, shareNameInvalidChars)
189→	}
190→	for _, r := range s.Name {
191→		if r < 0x20 || r == 0x7f {
192→			errs.add(prefix+".name", "共享名 %q 含控制字符 U+%04X", s.Name, r)
193→			break
194→		}
195→	}
196→
197→	// 保留名：IPC$ 由服务端内建（srvsvc 命名管道），不允许用户占用。
198→	lower := strings.ToLower(s.Name)
199→	if lower == "ipc$" {
200→		errs.add(prefix+".name", "%q 是服务端保留共享名，请换一个", s.Name)
201→	}
202→
203→	// SMB 共享名大小写不敏感，重名判定也必须不敏感。
204→	if prev, ok := seen[lower]; ok {
205→		errs.add(prefix+".name", "共享名 %q 与 shares[%d] 重复（共享名大小写不敏感）", s.Name, prev)
206→	} else {
207→		seen[lower] = idx
208→	}
209→}
210→
211→func validateSharePath(s *Share, prefix string, errs *ValidationErrors) {
212→	if s.Path == "" {
213→		errs.add(prefix+".path", "共享 %q 未指定本地目录路径", s.Name)
214→		return
215→	}
216→	if !isAbsPath(s.Path) {
217→		errs.add(prefix+".path", "共享 %q 的路径必须是绝对路径，当前 %q", s.Name, s.Path)
218→		return
219→	}
220→
221→	fi, err := os.Stat(s.Path)
222→	if err != nil {
223→		switch {
224→		case os.IsNotExist(err):
225→			errs.add(prefix+".path", "共享 %q 的目录不存在: %s", s.Name, s.Path)
226→		case os.IsPermission(err):
227→			errs.add(prefix+".path", "共享 %q 的目录无权访问: %s", s.Name, s.Path)
228→		default:
229→			errs.add(prefix+".path", "共享 %q 的目录无法访问: %v", s.Name, err)
230→		}
231→		return
232→	}
233→	if !fi.IsDir() {
234→		errs.add(prefix+".path", "共享 %q 的路径不是目录: %s", s.Name, s.Path)
235→	}
236→}
237→
238→// validateShareMetadataPath 校验 POSIX 元数据旁路存储路径（仅 Windows 生效）。
239→//
240→// 只校验"路径本身写得对不对"，文件存不存在由 vfs 层在启动时创建。
241→func validateShareMetadataPath(s *Share, prefix string, errs *ValidationErrors) {
242→	if s.MetadataPath == "" {
243→		return
244→	}
245→	field := prefix + ".metadata_path"
246→	if !isAbsPath(s.MetadataPath) {
247→		errs.add(field, "共享 %q 的 metadata_path 必须是绝对路径，当前 %q", s.Name, s.MetadataPath)
248→		return
249→	}
250→
251→	// 父目录必须已存在，否则 vfs 启动时创建 KV 数据库会失败。
252→	dir := filepath.Dir(s.MetadataPath)
253→	fi, err := os.Stat(dir)
254→	switch {
255→	case err != nil && os.IsNotExist(err):
256→		errs.add(field, "共享 %q 的 metadata_path 所在目录不存在: %s", s.Name, dir)
257→	case err != nil:
258→		errs.add(field, "共享 %q 的 metadata_path 所在目录无法访问: %v", s.Name, err)
259→	case !fi.IsDir():
260→		errs.add(field, "共享 %q 的 metadata_path 所在路径不是目录: %s", s.Name, dir)
261→	}
262→}
263→
264→func validateAuth(c *Config, errs *ValidationErrors) {
265→	seen := make(map[string]int, len(c.Auth.Users))
266→	for i := range c.Auth.Users {
267→		u := &c.Auth.Users[i]
268→		prefix := fmt.Sprintf("auth.users[%d]", i)
269→
270→		if u.Name == "" {
271→			errs.add(prefix+".name", "用户名不能为空")
272→		} else {
273→			lower := strings.ToLower(u.Name)
274→			if prev, ok := seen[lower]; ok {
275→				errs.add(prefix+".name", "用户名 %q 与 auth.users[%d] 重复（用户名大小写不敏感）", u.Name, prev)
276→			} else {
277→				seen[lower] = i
278→			}
279→			if lower == "guest" {
280→				errs.add(prefix+".name", "%q 是保留用户名，guest 行为由 auth.allow_guest 控制", u.Name)
281→			}
282→		}
283→
284→		switch {
285→		case u.Password == "" && u.NTHash == "":
286→			errs.add(prefix, "用户 %q 必须提供 password 或 nt_hash 之一", u.Name)
287→		case u.NTHash != "":
288→			if !isHex32(u.NTHash) {
289→				errs.add(prefix+".nt_hash", "用户 %q 的 nt_hash 必须是 32 位十六进制字符串（MD4(UTF16LE(password))），当前 %d 个字符", u.Name, len(u.NTHash))
290→			}
291→		}
292→	}
293→
294→	if !c.Auth.AllowGuest && len(c.Auth.Users) == 0 {
295→		errs.add("auth", "allow_guest 为 false 且未配置任何用户，没有人能登录这台服务器")
296→	}
297→
298→	// valid_users 引用的用户必须存在，否则该共享谁都进不去。
299→	for i := range c.Shares {
300→		s := &c.Shares[i]
301→		for j, name := range s.ValidUsers {
302→			if _, ok := seen[strings.ToLower(name)]; !ok {
303→				errs.add(fmt.Sprintf("shares[%d].valid_users[%d]", i, j),
304→					"共享 %q 引用了未定义的用户 %q（请先在 auth.users 里定义）", s.Name, name)
305→			}
306→		}
307→	}
308→}
309→
310→func validateMDNS(c *Config, errs *ValidationErrors) {
311→	if !c.MDNS.Enabled {
312→		return
313→	}
314→
315→	// RFC 6763 §4.1.1：实例名是一个 DNS label，UTF-8 编码后不得超过 63 字节。
316→	if n := len(c.MDNS.Instance); n > 63 {
317→		errs.add("mdns.instance", "实例名 UTF-8 编码后 %d 字节，超过 DNS label 上限 63 字节", n)
318→	}
319→	if strings.ContainsAny(c.MDNS.Instance, "\x00.") {
320→		errs.add("mdns.instance", "实例名不能含点号或 NUL: %q", c.MDNS.Instance)
321→	}
322→
323→	for i, name := range c.MDNS.Interfaces {
324→		field := fmt.Sprintf("mdns.interfaces[%d]", i)
325→		if name == "" {
326→			errs.add(field, "网卡名不能为空（若要使用全部网卡请把 interfaces 整个留空）")
327→			continue
328→		}
329→		if _, err := net.InterfaceByName(name); err != nil {
330→			errs.add(field, "找不到网卡 %q: %v", name, err)
331→		}
332→	}
333→
334→	if c.MDNS.Apple.Enabled && c.MDNS.Apple.Model == "" {
335→		errs.add("mdns.apple.model", "启用 Apple 扩展时 model 不能为空（决定 Finder 中显示的图标）")
336→	}
337→	// _device-info._tcp 的 model= 是单条 TXT 记录，长度上限 255 字节（RFC 6763 §6.1）。
338→	if n := len(c.MDNS.Apple.Model); n > 200 {
339→		errs.add("mdns.apple.model", "model 过长（%d 字节），单条 TXT 记录上限 255 字节", n)
340→	}
341→
342→	if c.MDNS.Apple.AdvertiseTimeMachine && !c.MDNS.Apple.Enabled {
343→		errs.add("mdns.apple.advertise_time_machine", "需要同时设置 mdns.apple.enabled: true")
344→	}
345→	if c.MDNS.Apple.AdvertiseTimeMachine && !hasTimeMachineShare(c) {
346→		errs.add("mdns.apple.advertise_time_machine", "已开启 Time Machine 广播，但没有任何共享设置 time_machine: true")
347→	}
348→}
349→
350→func hasTimeMachineShare(c *Config) bool {
351→	for i := range c.Shares {
352→		if c.Shares[i].TimeMachine {
353→			return true
354→		}
355→	}
356→	return false
357→}
358→
359→func validateLog(c *Config, errs *ValidationErrors) {
360→	switch c.Log.Level {
361→	case "debug", "info", "warn", "error":
362→	default:
363→		errs.add("log.level", "非法日志级别 %q，可选值: debug, info, warn, error", c.Log.Level)
364→	}
365→	switch c.Log.Format {
366→	case "text", "json":
367→	default:
368→		errs.add("log.format", "非法日志格式 %q，可选值: text, json", c.Log.Format)
369→	}
370→	if c.Log.File != "" && !isAbsPath(c.Log.File) {
371→		errs.add("log.file", "日志文件必须是绝对路径，当前 %q", c.Log.File)
372→	}
373→}
374→
375→// Warnings 返回配置合法但值得提醒用户的问题。
376→//
377→// 与 Validate 分开：这些不阻止启动，但必须在日志里以 WARN 级别打出来。
378→func Warnings(c *Config) []string {
379→	var w []string
380→
381→	// 445 是特权端口，非 root 且无 CAP_NET_BIND_SERVICE 时 bind 会失败，
382→	// 这是最常见的启动失败原因，提前提示。
383→	//
384→	// Windows 没有特权端口的概念（也没有 euid，os.Geteuid 恒返回 -1），
385→	// 在那里提示会是纯噪音，因此跳过。
386→	if c.Listen.Port < 1024 && runtime.GOOS != "windows" && os.Geteuid() != 0 {
387→		w = append(w, fmt.Sprintf(
388→			"listen.port=%d 是特权端口（<1024），当前不是 root。"+
389→				"请以 root 运行，或执行 setcap 'cap_net_bind_service=+ep' <二进制>，"+
390→				"或改用 >=1024 的端口", c.Listen.Port))
391→	}
392→
393→	if c.Auth.AllowGuest {
394→		w = append(w, "auth.allow_guest=true：任何人都可以匿名访问共享，请确认这是你想要的"+
395→			"（注意 Windows 10/11 默认拒绝不安全的 guest 登录）")
396→	}
397→
398→	for i := range c.Shares {
399→		s := &c.Shares[i]
400→		if s.GuestOK && !c.Auth.AllowGuest {
401→			w = append(w, fmt.Sprintf("shares[%d] %q 设置了 guest_ok 但 auth.allow_guest=false，该设置不会生效", i, s.Name))
402→		}
403→		// quota_bytes 太小（< 1 GiB）时 Time Machine 会反复备份失败、
404→		// 空间抖动，真实 NAS 都设下限。这里只 WARN 不报错：用户可能有意为之。
405→		if s.QuotaBytes != 0 && s.QuotaBytes < quotaMinWarn {
406→			w = append(w, fmt.Sprintf("shares[%d] %q 的 quota_bytes=%d 小于 1 GiB，Time Machine 在过小的卷上会反复失败", i, s.Name, s.QuotaBytes))
407→		}
408→		if s.MetadataPath == "" {
409→			continue
410→		}
411→		// POSIX 元数据旁路存储只在 Windows 编译进来（AGENTS.md §5 P7）。
412→		if runtime.GOOS != "windows" {
413→			w = append(w, fmt.Sprintf("shares[%d] %q 设置了 metadata_path，但该字段仅在 Windows 上生效，当前平台（%s）会忽略它",
414→				i, s.Name, runtime.GOOS))
415→		}
416→		if isUnderDir(s.MetadataPath, s.Path) {
417→			w = append(w, fmt.Sprintf("shares[%d] %q 的 metadata_path 位于共享目录内部，客户端会看到这个数据库文件，建议放到共享之外",
418→				i, s.Name))
419→		}
420→	}
421→
422→	for i := range c.Auth.Users {
423→		if c.Auth.Users[i].Password != "" {
424→			w = append(w, fmt.Sprintf("auth.users[%d] %q 使用明文口令，建议改用 nt_hash 避免口令落盘",
425→				i, c.Auth.Users[i].Name))
426→		}
427→	}
428→
429→	if !c.Server.SigningRequired {
430→		w = append(w, "server.signing_required=false：未强制 SMB 签名，存在中间人篡改风险")
431→	}
432→
433→	return w
434→}
435→
436→// isUnderDir 判断 p 是否位于目录 dir 之内（不含 dir 自身）。
437→//
438→// 只做词法比较，不解析符号链接 —— 这里只用于生成提示，不用于安全判定。
439→func isUnderDir(p, dir string) bool {
440→	if p == "" || dir == "" {
441→		return false
442→	}
443→	rel, err := filepath.Rel(filepath.Clean(dir), filepath.Clean(p))
444→	if err != nil {
445→		return false
446→	}
447→	return rel != "." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && rel != ".."
448→}
449→
450→// isHex32 判断是否为 32 位十六进制字符串。
451→func isHex32(s string) bool {
452→	if len(s) != 32 {
453→		return false
454→	}
455→	for i := 0; i < len(s); i++ {
456→		c := s[i]
457→		if (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F') {
458→			continue
459→		}
460→		return false
461→	}
462→	return true
463→}
