  1→package config
  2→
  3→import (
  4→	"fmt"
  5→	"net"
  6→	"os"
  7→	"path/filepath"
  8→	"runtime"
  9→	"strings"
 10→)
 11→
 12→// isAbsPath 判断是否为**本平台**的绝对路径。
 13→// 用 filepath 而非 path，以便 Windows 上 "C:\share" 也算绝对路径（AGENTS.md C7）。
 14→func isAbsPath(p string) bool { return filepath.IsAbs(p) }
 15→
 16→// quotaMinWarn 是 quota_bytes 的建议下限（1 GiB）。
 17→// 低于此值的卷容量上报对 Time Machine 不实用（会反复失败、空间抖动），
 18→// 但用户可能确有意图，所以只是 WARN，不报错。
 19→const quotaMinWarn = 1 << 30
 20→
 21→// FieldError 是单个字段的校验错误。
 22→//
 23→// Field 用 YAML 路径表示（如 "shares[1].path"），方便用户直接定位到配置行。
 24→type FieldError struct {
 25→	Field string
 26→	Msg   string
 27→}
 28→
 29→func (e FieldError) Error() string { return e.Field + ": " + e.Msg }
 30→
 31→// ValidationErrors 汇总一次校验中发现的**全部**问题。
 32→//
 33→// 一次性报出所有错误，避免用户改一个跑一次。
 34→type ValidationErrors []FieldError
 35→
 36→func (e ValidationErrors) Error() string {
 37→	if len(e) == 1 {
 38→		return "配置校验失败: " + e[0].Error()
 39→	}
 40→	var b strings.Builder
 41→	fmt.Fprintf(&b, "配置校验失败，共 %d 处问题:", len(e))
 42→	for _, fe := range e {
 43→		b.WriteString("\n  - " + fe.Error())
 44→	}
 45→	return b.String()
 46→}
 47→
 48→// add 追加一条错误。
 49→func (e *ValidationErrors) add(field, format string, args ...any) {
 50→	*e = append(*e, FieldError{Field: field, Msg: fmt.Sprintf(format, args...)})
 51→}
 52→
 53→// 合法方言字符串，从低到高排列。索引即优先级。
 54→//
 55→// MS-SMB2 §2.2.3：0x0202 / 0x0210 / 0x0300 / 0x0302 / 0x0311。
 56→// 这里只做字符串校验，不引入 internal/smb（config 不依赖协议层）。
 57→var dialectOrder = []string{"2.0.2", "2.1", "3.0", "3.0.2", "3.1.1"}
 58→
 59→// DialectNames 返回全部合法的方言字符串（从低到高）。
 60→func DialectNames() []string {
 61→	out := make([]string, len(dialectOrder))
 62→	copy(out, dialectOrder)
 63→	return out
 64→}
 65→
 66→// dialectRank 返回方言的序号，非法返回 -1。
 67→func dialectRank(s string) int {
 68→	for i, d := range dialectOrder {
 69→		if d == s {
 70→			return i
 71→		}
 72→	}
 73→	return -1
 74→}
 75→
 76→// 共享名非法字符。
 77→//
 78→// MS-SRVS §2.2.4.22 / Windows 约定：共享名不得包含以下字符，
 79→// 也不得包含控制字符。长度上限 80 个字符。
 80→const shareNameInvalidChars = `\/:*?"<>|+;,=[]` + "\x00"
 81→
 82→// ShareNameMaxLen 是共享名最大长度（MS-SRVS 约定 80）。
 83→const ShareNameMaxLen = 80
 84→
 85→// Validate 校验配置。调用前应先执行 ApplyDefaults。
 86→//
 87→// 返回的 error 若非 nil，其动态类型一定是 ValidationErrors。
 88→func Validate(c *Config) error {
 89→	var errs ValidationErrors
 90→
 91→	validateServer(c, &errs)
 92→	validateListen(c, &errs)
 93→	validateShares(c, &errs)
 94→	validateAuth(c, &errs)
 95→	validateMDNS(c, &errs)
 96→	validateLog(c, &errs)
 97→
 98→	if len(errs) == 0 {
 99→		return nil
100→	}
101→	return errs
102→}
