142→func validateListen(c *Config, errs *ValidationErrors) {
143→	for i, a := range c.Listen.Addresses {
144→		field := fmt.Sprintf("listen.addresses[%d]", i)
145→		if a == "" {
146→			errs.add(field, "不能为空字符串（若要监听全部地址请把 addresses 整个留空）")
147→			continue
148→		}
149→		if net.ParseIP(a) == nil {
150→			errs.add(field, "不是合法 IP 地址: %q（这里只接受 IP，不接受主机名，端口写在 listen.port）", a)
151→		}
152→	}
153→
154→	if c.Listen.Port < 1 || c.Listen.Port > 65535 {
155→		errs.add("listen.port", "端口必须在 1-65535 之间，当前 %d", c.Listen.Port)
156→	}
157→}
