264→func validateAuth(c *Config, errs *ValidationErrors) {
265→	seen := make(map[string]int, len(c.Auth.Users))
266→	for i := range c.Auth.Users {
267→		u := &c.Auth.Users[i]
268→		prefix := fmt.Sprintf("auth.users[%d]", i)
269→
270→		if u.Name == "" {
271→			errs.add(prefix+".name", "用户名不能为空")
272→		} else {
273→			lower := strings.ToLower(u.Name)
274→			if prev, ok := seen[lower]; ok {
275→				errs.add(prefix+".name", "用户名 %q 与 auth.users[%d] 重复（用户名大小写不敏感）", u.Name, prev)
276→			} else {
277→				seen[lower] = i
278→			}
279→			if lower == "guest" {
280→				errs.add(prefix+".name", "%q 是保留用户名，guest 行为由 auth.allow_guest 控制", u.Name)
281→			}
282→		}
283→
284→		switch {
285→		case u.Password == "" && u.NTHash == "":
286→			errs.add(prefix, "用户 %q 必须提供 password 或 nt_hash 之一", u.Name)
287→		case u.NTHash != "":
288→			if !isHex32(u.NTHash) {
289→				errs.add(prefix+".nt_hash", "用户 %q 的 nt_hash 必须是 32 位十六进制字符串（MD4(UTF16LE(password))），当前 %d 个字符", u.Name, len(u.NTHash))
290→			}
291→		}
292→	}
293→
294→	if !c.Auth.AllowGuest && len(c.Auth.Users) == 0 {
295→		errs.add("auth", "allow_guest 为 false 且未配置任何用户，没有人能登录这台服务器")
296→	}
297→
298→	// valid_users 引用的用户必须存在，否则该共享谁都进不去。
299→	for i := range c.Shares {
300→		s := &c.Shares[i]
301→		for j, name := range s.ValidUsers {
302→			if _, ok := seen[strings.ToLower(name)]; !ok {
303→				errs.add(fmt.Sprintf("shares[%d].valid_users[%d]", i, j),
304→					"共享 %q 引用了未定义的用户 %q（请先在 auth.users 里定义）", s.Name, name)
305→			}
306→		}
307→	}
308→}
