310→func validateMDNS(c *Config, errs *ValidationErrors) {
311→	if !c.MDNS.Enabled {
312→		return
313→	}
314→
315→	// RFC 6763 §4.1.1：实例名是一个 DNS label，UTF-8 编码后不得超过 63 字节。
316→	if n := len(c.MDNS.Instance); n > 63 {
317→		errs.add("mdns.instance", "实例名 UTF-8 编码后 %d 字节，超过 DNS label 上限 63 字节", n)
318→	}
319→	if strings.ContainsAny(c.MDNS.Instance, "\x00.") {
320→		errs.add("mdns.instance", "实例名不能含点号或 NUL: %q", c.MDNS.Instance)
321→	}
322→
323→	for i, name := range c.MDNS.Interfaces {
324→		field := fmt.Sprintf("mdns.interfaces[%d]", i)
325→		if name == "" {
326→			errs.add(field, "网卡名不能为空（若要使用全部网卡请把 interfaces 整个留空）")
327→			continue
328→		}
329→		if _, err := net.InterfaceByName(name); err != nil {
330→			errs.add(field, "找不到网卡 %q: %v", name, err)
331→		}
332→	}
333→
334→	if c.MDNS.Apple.Enabled && c.MDNS.Apple.Model == "" {
335→		errs.add("mdns.apple.model", "启用 Apple 扩展时 model 不能为空（决定 Finder 中显示的图标）")
336→	}
337→	// _device-info._tcp 的 model= 是单条 TXT 记录，长度上限 255 字节（RFC 6763 §6.1）。
338→	if n := len(c.MDNS.Apple.Model); n > 200 {
339→		errs.add("mdns.apple.model", "model 过长（%d 字节），单条 TXT 记录上限 255 字节", n)
340→	}
341→
342→	if c.MDNS.Apple.AdvertiseTimeMachine && !c.MDNS.Apple.Enabled {
343→		errs.add("mdns.apple.advertise_time_machine", "需要同时设置 mdns.apple.enabled: true")
344→	}
345→	if c.MDNS.Apple.AdvertiseTimeMachine && !hasTimeMachineShare(c) {
346→		errs.add("mdns.apple.advertise_time_machine", "已开启 Time Machine 广播，但没有任何共享设置 time_machine: true")
347→	}
348→}
