359→func validateLog(c *Config, errs *ValidationErrors) {
360→	switch c.Log.Level {
361→	case "debug", "info", "warn", "error":
362→	default:
363→		errs.add("log.level", "非法日志级别 %q，可选值: debug, info, warn, error", c.Log.Level)
364→	}
365→	switch c.Log.Format {
366→	case "text", "json":
367→	default:
368→		errs.add("log.format", "非法日志格式 %q，可选值: text, json", c.Log.Format)
369→	}
370→	if c.Log.File != "" && !isAbsPath(c.Log.File) {
371→		errs.add("log.file", "日志文件必须是绝对路径，当前 %q", c.Log.File)
372→	}
373→}
