375→// Warnings 返回配置合法但值得提醒用户的问题。
376→//
377→// 与 Validate 分开：这些不阻止启动，但必须在日志里以 WARN 级别打出来。
378→func Warnings(c *Config) []string {
379→	var w []string
380→
381→	// 445 是特权端口，非 root 且无 CAP_NET_BIND_SERVICE 时 bind 会失败，
382→	// 这是最常见的启动失败原因，提前提示。
383→	//
384→	// Windows 没有特权端口的概念（也没有 euid，os.Geteuid 恒返回 -1），
385→	// 在那里提示会是纯噪音，因此跳过。
386→	if c.Listen.Port < 1024 && runtime.GOOS != "windows" && os.Geteuid() != 0 {
387→		w = append(w, fmt.Sprintf(
388→			"listen.port=%d 是特权端口（<1024），当前不是 root。"+
389→				"请以 root 运行，或执行 setcap 'cap_net_bind_service=+ep' <二进制>，"+
390→				"或改用 >=1024 的端口", c.Listen.Port))
391→	}
392→
393→	if c.Auth.AllowGuest {
394→		w = append(w, "auth.allow_guest=true：任何人都可以匿名访问共享，请确认这是你想要的"+
395→			"（注意 Windows 10/11 默认拒绝不安全的 guest 登录）")
396→	}
397→
398→	for i := range c.Shares {
399→		s := &c.Shares[i]
400→		if s.GuestOK && !c.Auth.AllowGuest {
401→			w = append(w, fmt.Sprintf("shares[%d] %q 设置了 guest_ok 但 auth.allow_guest=false，该设置不会生效", i, s.Name))
402→		}
403→		// quota_bytes 太小（< 1 GiB）时 Time Machine 会反复备份失败、
404→		// 空间抖动，真实 NAS 都设下限。这里只 WARN 不报错：用户可能有意为之。
405→		if s.QuotaBytes != 0 && s.QuotaBytes < quotaMinWarn {
406→			w = append(w, fmt.Sprintf("shares[%d] %q 的 quota_bytes=%d 小于 1 GiB，Time Machine 在过小的卷上会反复失败", i, s.Name, s.QuotaBytes))
407→		}
408→		if s.MetadataPath == "" {
409→			continue
410→		}
411→		// POSIX 元数据旁路存储只在 Windows 编译进来（AGENTS.md §5 P7）。
412→		if runtime.GOOS != "windows" {
413→			w = append(w, fmt.Sprintf("shares[%d] %q 设置了 metadata_path，但该字段仅在 Windows 上生效，当前平台（%s）会忽略它",
414→				i, s.Name, runtime.GOOS))
415→		}
416→		if isUnderDir(s.MetadataPath, s.Path) {
417→			w = append(w, fmt.Sprintf("shares[%d] %q 的 metadata_path 位于共享目录内部，客户端会看到这个数据库文件，建议放到共享之外",
418→				i, s.Name))
419→		}
420→	}
421→
422→	for i := range c.Auth.Users {
423→		if c.Auth.Users[i].Password != "" {
424→			w = append(w, fmt.Sprintf("auth.users[%d] %q 使用明文口令，建议改用 nt_hash 避免口令落盘",
425→				i, c.Auth.Users[i].Name))
426→		}
427→	}
428→
429→	if !c.Server.SigningRequired {
430→		w = append(w, "server.signing_required=false：未强制 SMB 签名，存在中间人篡改风险")
431→	}
432→
433→	return w
434→}
435→
436→// isUnderDir 判断 p 是否位于目录 dir 之内（不含 dir 自身）。
437→//
438→// 只做词法比较，不解析符号链接 —— 这里只用于生成提示，不用于安全判定。
439→func isUnderDir(p, dir string) bool {
440→	if p == "" || dir == "" {
441→		return false
442→	}
443→	rel, err := filepath.Rel(filepath.Clean(dir), filepath.Clean(p))
444→	if err != nil {
445→		return false
446→	}
447→	return rel != "." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && rel != ".."
448→}
449→
450→// isHex32 判断是否为 32 位十六进制字符串。
451→func isHex32(s string) bool {
452→	if len(s) != 32 {
453→		return false
454→	}
455→	for i := 0; i < len(s); i++ {
456→		c := s[i]
457→		if (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F') {
458→			continue
459→		}
460→		return false
461→	}
462→	return true
463→}
