  1→//go:build integration
  2→
  3→// 端到端验证：真的在 224.0.0.251:5353 上收发报文（AGENTS.md C4）。
  4→//
  5→// 需要能加入组播组的运行环境，因此用 integration build tag 隔离：
  6→//
  7→//	go test -tags integration ./internal/mdns/ -run TestResponder -v
  8→package mdns
  9→
 10→import (
 11→	"context"
 12→	"io"
 13→	"log/slog"
 14→	"net"
 15→	"strings"
 16→	"testing"
 17→	"time"
 18→
 19→	"golang.org/x/net/ipv4"
 20→
 21→	"github.com/finalappstore/stupidsamba/internal/config"
 22→)
 23→
 24→// TestResponderAnswersLegacyQuery 用一个源端口 ≠5353 的普通 UDP socket 发查询，
 25→// 按 RFC 6762 §5.5 我们必须**单播**回应，于是不需要客户端也加入组播组。
 26→func TestResponderAnswersLegacyQuery(t *testing.T) {
 27→	const instance = "SSITEST"
 28→
 29→	r, err := New(config.MDNS{
 30→		Enabled:  true,
 31→		Instance: instance,
 32→		Apple: config.AppleMDNS{
 33→			Enabled:              true,
 34→			Model:                "TimeCapsule8,119",
 35→			AdvertiseTimeMachine: true,
 36→		},
 37→	}, 4445, []config.Share{
 38→		{Name: "data"},
 39→		{Name: "backup", TimeMachine: true},
 40→	})
 41→	if err != nil {
 42→		t.Fatalf("New: %v", err)
 43→	}
 44→	r.SetLogger(slog.New(slog.NewTextHandler(io.Discard, nil)))
 45→
 46→	if err := r.Start(context.Background()); err != nil {
 47→		t.Skipf("跳过：当前环境无法加入 mDNS 组播组: %v", err)
 48→	}
 49→	defer r.Stop()
 50→
 51→	// 等探测 + 首次宣告结束，此时才会应答查询。
 52→	deadline := time.Now().Add(5 * time.Second)
 53→	for r.currentState() != stateResponding {
 54→		if time.Now().After(deadline) {
 55→			t.Fatal("responder 迟迟没有进入应答状态")
 56→		}
 57→		time.Sleep(50 * time.Millisecond)
 58→	}
 59→
 60→	pc := newQuerySocket(t)
 61→	defer pc.Close()
 62→
 63→	q := &Message{Questions: []Question{
 64→		{Name: serviceTypeSMB + "." + localDomain, Type: TypePTR, Class: ClassIN},
 65→	}}
 66→	raw, err := q.Pack()
 67→	if err != nil {
 68→		t.Fatalf("Pack: %v", err)
 69→	}
 70→	if _, err := pc.WriteToUDP(raw, &net.UDPAddr{IP: mdnsGroupIPv4, Port: mdnsPort}); err != nil {
 71→		t.Skipf("跳过：发不出组播报文: %v", err)
 72→	}
 73→
 74→	// 收集回应里的记录，直到超时。
 75→	_ = pc.SetReadDeadline(time.Now().Add(3 * time.Second))
 76→	buf := make([]byte, maxPacketSize)
 77→
 78→	var got []Record
 79→	for {
 80→		n, _, err := pc.ReadFromUDP(buf)
 81→		if err != nil {
 82→			break
 83→		}
 84→		m, err := Unpack(buf[:n])
 85→		if err != nil || !m.Flags.IsResponse() {
 86→			continue
 87→		}
 88→		got = append(got, m.Answers...)
 89→		got = append(got, m.Additionals...)
 90→		if hasType(got, TypePTR) && hasType(got, TypeSRV) && hasType(got, TypeTXT) && hasType(got, TypeA) {
 91→			break
 92→		}
 93→	}
 94→
 95→	if len(got) == 0 {
 96→		t.Fatal("没有收到任何回应")
 97→	}
 98→
 99→	wantInstance := instance + "." + serviceTypeSMB + "." + localDomain
100→	var ptr, srv, txt, a bool
101→	for _, rec := range got {
102→		switch d := rec.Data.(type) {
103→		case PTR:
104→			if EqualName(rec.Name, serviceTypeSMB+"."+localDomain) && EqualName(d.Target, wantInstance) {
105→				ptr = true
106→			}
107→		case SRV:
108→			if EqualName(rec.Name, wantInstance) {
109→				if d.Port != 4445 {
110→					t.Errorf("SRV 端口 = %d, 期望 4445", d.Port)
111→				}
112→				srv = true
113→			}
114→		case TXT:
115→			if EqualName(rec.Name, wantInstance) {
116→				txt = true
117→			}
118→		case A:
119→			a = true
120→		}
121→		// RFC 6762 §6.7：传统单播回应的 TTL 必须压到 10 秒以内。
122→		if rec.TTL > legacyTTL {
123→			t.Errorf("记录 %s 的 TTL=%d 超过传统单播上限 %d", rec.Name, rec.TTL, legacyTTL)
124→		}
125→		// §6.7：传统客户端不认识 cache-flush 位。
126→		if rec.CacheFlush {
127→			t.Errorf("记录 %s 对传统单播查询带了 cache-flush 位", rec.Name)
128→		}
129→	}
130→
131→	if !ptr {
132→		t.Errorf("回应里缺少指向 %s 的 PTR", wantInstance)
133→	}
134→	if !srv {
135→		t.Errorf("回应里缺少 %s 的 SRV", wantInstance)
136→	}
137→	if !txt {
138→		t.Errorf("回应里缺少 %s 的 TXT", wantInstance)
139→	}
140→	if !a {
141→		t.Errorf("回应里缺少 A 记录（附加段应当带上地址）")
142→	}
143→}
