145→// TestResponderMetaQuery 验证 DNS-SD 服务类型枚举（RFC 6763 §9）：
146→// 查询 _services._dns-sd._udp.local. 应当列出我们提供的所有服务类型。
147→func TestResponderMetaQuery(t *testing.T) {
148→	r, err := New(config.MDNS{
149→		Enabled:  true,
150→		Instance: "SSMETA",
151→		Apple:    config.AppleMDNS{Enabled: true, Model: "MacSamba"},
152→	}, 4446, nil)
153→	if err != nil {
154→		t.Fatalf("New: %v", err)
155→	}
156→	r.SetLogger(slog.New(slog.NewTextHandler(io.Discard, nil)))
157→
158→	if err := r.Start(context.Background()); err != nil {
159→		t.Skipf("跳过：当前环境无法加入 mDNS 组播组: %v", err)
160→	}
161→	defer r.Stop()
162→
163→	deadline := time.Now().Add(5 * time.Second)
164→	for r.currentState() != stateResponding {
165→		if time.Now().After(deadline) {
166→			t.Fatal("responder 迟迟没有进入应答状态")
167→		}
168→		time.Sleep(50 * time.Millisecond)
169→	}
170→
171→	pc := newQuerySocket(t)
172→	defer pc.Close()
173→
174→	q := &Message{Questions: []Question{{Name: metaQueryName, Type: TypePTR, Class: ClassIN}}}
175→	raw, err := q.Pack()
176→	if err != nil {
177→		t.Fatalf("Pack: %v", err)
178→	}
179→	if _, err := pc.WriteToUDP(raw, &net.UDPAddr{IP: mdnsGroupIPv4, Port: mdnsPort}); err != nil {
180→		t.Skipf("跳过：发不出组播报文: %v", err)
181→	}
182→
183→	_ = pc.SetReadDeadline(time.Now().Add(3 * time.Second))
184→	buf := make([]byte, maxPacketSize)
185→
186→	types := map[string]bool{}
187→	for {
188→		n, _, err := pc.ReadFromUDP(buf)
189→		if err != nil {
190→			break
191→		}
192→		m, err := Unpack(buf[:n])
193→		if err != nil || !m.Flags.IsResponse() {
194→			continue
195→		}
196→		for _, rec := range m.Answers {
197→			if !EqualName(rec.Name, metaQueryName) {
198→				continue
199→			}
200→			if d, ok := rec.Data.(PTR); ok {
201→				types[strings.ToLower(d.Target)] = true
202→			}
203→		}
204→		if len(types) >= 2 {
205→			break
206→		}
207→	}
208→
209→	for _, want := range []string{serviceTypeSMB, serviceTypeDeviceInfo} {
210→		if !types[strings.ToLower(want+"."+localDomain)] {
211→			t.Errorf("服务类型枚举里缺少 %s（收到 %v）", want, keysOf(types))
212→		}
213→	}
214→}
