216→// newQuerySocket 建一个普通（未加入组播组）的 UDP socket 用来发查询。
217→//
218→// 关键：组播 TTL 必须设成 255。RFC 6762 §11 要求响应者丢弃 TTL≠255 的报文，
219→// 而 Go 的默认组播 TTL 是 1 —— 忘了设的话我们自己的 responder 会正确地
220→// 把测试报文丢掉，表现为"没有收到任何回应"。
221→func newQuerySocket(t *testing.T) *net.UDPConn {
222→	t.Helper()
223→	pc, err := net.ListenUDP("udp4", &net.UDPAddr{IP: net.IPv4zero, Port: 0})
224→	if err != nil {
225→		t.Fatalf("客户端 socket: %v", err)
226→	}
227→	p := ipv4.NewPacketConn(pc)
228→	if err := p.SetMulticastTTL(mdnsTTL); err != nil {
229→		pc.Close()
230→		t.Fatalf("设置组播 TTL: %v", err)
231→	}
232→	_ = p.SetMulticastLoopback(true)
233→	return pc
234→}
235→
236→func hasType(recs []Record, t Type) bool {
237→	for _, r := range recs {
238→		if r.Type() == t {
239→			return true
240→		}
241→	}
242→	return false
243→}
244→
245→func keysOf(m map[string]bool) []string {
246→	out := make([]string, 0, len(m))
247→	for k := range m {
248→		out = append(out, k)
249→	}
250→	return out
251→}
