func startServer(t *testing.T, bin string, port int) *smokeServer {
	t.Helper()

	dir := t.TempDir()
	share := filepath.Join(dir, "share")
	if err := os.MkdirAll(share, 0o755); err != nil {
		t.Fatal(err)
	}

