	// 与本测试要验的退出流程无关，开着只会引入偶发失败。
	cfg := fmt.Sprintf(`server:
  name: SMOKETEST
listen:
  addresses: ["127.0.0.1"]
  port: %d
auth:
  users:
    - name: alice
      password: "smoke-secret"
shares:
  - name: data
    path: %s
mdns:
  enabled: false
log:
  level: debug
